use vstd::prelude::*;

verus! {
    // Copy the contents of a vector into a new vector.
    // T is assumed Copy so we can duplicate elements by value.
    fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
        ensures
            // The resulting vector has exactly the same sequence of elements
            // as the original.
            result@ == a@,
    {
        let mut res: Vec<T> = Vec::new();
        let mut i: usize = 0;
        // We maintain that res@ is exactly the first i elements of a@.
        while i < a.len()
            invariant
                res@ == Seq::take(a@, i),
            decreases
                a.len() - i,
        {
            // Copy the i-th element of `a` into `res`.
            res.push(a[i]);
            i = i + 1;
        }
        res
    }
}

fn main() {
    // Example usage (not verified):
    let v = Vec::from_slice(&[1u8, 2, 3, 4]);
    let w = copy(&v);
    assert!(w[..] == v[..]);
}